// The generated native binding as a script reaches it: the fixture script API of the binding
// generators (Tools/ComponentScanner/Tests/Fixtures/Bindings), generated by this build and called
// through its table. The engine runs as a host owns it, so the thread rules apply.
#include "ProbeSystem.h"
#include "Probe.script.gen.h"

#include "Core/Engine.h"
#include "Mathematics/Curve.h"
#include "Mathematics/Geometry.h"
#include "Types/Color.h"

#include <gtest/gtest.h>

#include <algorithm>
#include <cstddef>
#include <string>
#include <string_view>
#include <thread>

using namespace GameEngine;
using namespace GameEngine::Probe;

namespace
{

constexpr StringId kSound = HashStringId("Probe.Sound");

const GE_Probe_Table_v1& Table()
{
    const void* table = nullptr;
    std::uint32_t size = 0;
    EXPECT_EQ(GE_Probe_GetInterface(GE_Probe_Hash, &table, &size), GE_Result_Ok);
    EXPECT_EQ(size, sizeof(GE_Probe_Table_v1));
    return *static_cast<const GE_Probe_Table_v1*>(table);
}

std::string LastError()
{
    std::string text(512, '\0');
    int32_t length = 0;
    EXPECT_EQ(GE_GetLastScriptError(text.data(), static_cast<int32_t>(text.size()), &length), GE_Result_Ok);
    text.resize(static_cast<std::size_t>(std::min<int32_t>(length, static_cast<int32_t>(text.size()))));
    return text;
}

class ScriptBindings : public testing::Test
{
  protected:
    static void SetUpTestSuite()
    {
        EngineCore& engine = EngineCore::GetInstance();
        if (engine.IsInitialized())
            return;
        ApplicationConfig config;
        config.AssetDirectory = "Assets";
        ScriptsConfig scripts{};
        scripts.enableHotReload = false;
        engine.SetScriptsConfig(scripts);
        ASSERT_TRUE(engine.Initialize(config));
    }

    void SetUp() override { ProbeSystem::Current() = &m_Probe; }
    void TearDown() override { ProbeSystem::Current() = nullptr; }

    ProbeSystem m_Probe;
};

} // namespace

TEST_F(ScriptBindings, TableCallsTheFacadeWithEveryArgument)
{
    const GE_Probe_Table_v1& table = Table();
    SoundOptions options;
    options.volume = 0.25f;
    std::uint8_t plays = 0;

    ASSERT_EQ(table.Play(kSound, &options, 0.75f, Loudness::Quiet, 6u, &plays), GE_Result_Ok);

    EXPECT_EQ(plays, 1u);
    EXPECT_EQ(m_Probe.LastSound, kSound);
    EXPECT_EQ(m_Probe.LastOptions.volume, 0.25f);
    EXPECT_EQ(m_Probe.LastGain, 0.75f);
    EXPECT_EQ(m_Probe.LastLoudness, Loudness::Quiet);
    EXPECT_EQ(m_Probe.LastLayers, 6u);

    ASSERT_EQ(table.SetFlag(1u, -3, 2.5), GE_Result_Ok);
    EXPECT_TRUE(m_Probe.Flag);
    EXPECT_EQ(m_Probe.Level, -3);
    EXPECT_EQ(m_Probe.Weight, 2.5);

    const Mathematics::Vector3 origin{1.0f, 2.0f, 3.0f};
    const Mathematics::Vector3 direction{0.0f, 0.0f, 1.0f};
    Hit hit;
    std::uint8_t found = 0;
    ASSERT_EQ(table.TryCast(&origin, &direction, &hit, 10.0f, &found), GE_Result_Ok);
    EXPECT_EQ(found, 1u);
    EXPECT_EQ(hit.distance, 10.0f);
    EXPECT_EQ(hit.point.z, 13.0f);
}

TEST_F(ScriptBindings, NullOutParameterIsRefusedBeforeTheCall)
{
    const std::uint32_t calls = ProbeSystem::Calls().load();
    SoundOptions options;

    EXPECT_EQ(Table().Play(kSound, &options, 0.5f, Loudness::Loud, 1u, nullptr), GE_Result_InvalidArg);
    EXPECT_EQ(Table().Play(kSound, nullptr, 0.5f, Loudness::Loud, 1u, nullptr), GE_Result_InvalidArg);

    EXPECT_EQ(ProbeSystem::Calls().load(), calls);
    EXPECT_NE(LastError().find("Probe.Play: `options` is a null pointer"), std::string::npos) << LastError();
}

TEST_F(ScriptBindings, StringIdZeroIsInvalidArg)
{
    SoundOptions options;
    std::uint8_t plays = 7;

    EXPECT_EQ(Table().Play(0, &options, 0.5f, Loudness::Loud, 1u, &plays), GE_Result_InvalidArg);

    EXPECT_EQ(m_Probe.LastSound, 0u) << "the facade was not called";
    EXPECT_NE(LastError().find("Probe.Play: `sound` is 0, which names no id"), std::string::npos) << LastError();
}

// A thread the engine does not run is refused by a main-thread function and an engine-thread one,
// with nothing called; an any-thread function answers it.
TEST_F(ScriptBindings, WrongThreadIsRefused)
{
    const GE_Probe_Table_v1& table = Table();
    const std::uint32_t calls = ProbeSystem::Calls().load();
    GE_Result setFlag = GE_Result_Ok;
    GE_Result tryCast = GE_Result_Ok;
    GE_Result callCount = GE_Result_Fail;
    std::string error;
    std::thread worker([&] {
        setFlag = table.SetFlag(1u, 1, 1.0);
        error = LastError();
        const Mathematics::Vector3 origin{};
        const Mathematics::Vector3 direction{0.0f, 1.0f, 0.0f};
        Hit hit;
        std::uint8_t found = 0;
        tryCast = table.TryCast(&origin, &direction, &hit, 1.0f, &found);
        std::uint32_t count = 0;
        callCount = table.CallCount(&count);
    });
    worker.join();

    EXPECT_EQ(setFlag, GE_Result_Fail);
    EXPECT_EQ(tryCast, GE_Result_Fail);
    EXPECT_EQ(callCount, GE_Result_Ok);
    EXPECT_FALSE(m_Probe.Flag);
    EXPECT_EQ(ProbeSystem::Calls().load(), calls);
    EXPECT_NE(error.find("Probe.SetFlag was called off the main thread and was refused"), std::string::npos) << error;
}

TEST_F(ScriptBindings, OtherHashIsRefused)
{
    const int stale = 0;
    const void* table = &stale;
    std::uint32_t size = 99;

    EXPECT_EQ(GE_Probe_GetInterface(GE_Probe_Hash ^ 1u, &table, &size), GE_Result_InvalidArg);

    EXPECT_EQ(table, nullptr);
    EXPECT_EQ(size, 0u);
    const std::string error = LastError();
    EXPECT_NE(error.find("The Probe binding was built from the script API with hash"), std::string::npos) << error;
    EXPECT_NE(error.find("If a *ScriptApi.h changed, build the UpdateEngineApi target and rebuild"), std::string::npos) << error;
}

TEST_F(ScriptBindings, MissingSystemAnswersNotInitializedWithDefaults)
{
    ProbeSystem::Current() = nullptr;
    SoundOptions options;
    options.volume = 0.0f;
    options.seed = 9;

    EXPECT_EQ(Table().GetLastOptions(&options), GE_Result_NotInitialized);

    EXPECT_EQ(options.volume, 1.0f) << "the out value holds the record's defaults";
    EXPECT_EQ(options.seed, -3);
}

// An out entity of a call that does not run names no entity, never entity 0.
TEST_F(ScriptBindings, OutEntityOfAMissingSystemIsTheInvalidEntity)
{
    ProbeSystem::Current() = nullptr;
    const Mathematics::Vector3 point{};
    std::uint32_t nearest = 0;
    std::uint8_t found = 1;

    EXPECT_EQ(Table().TryNearest(&point, &nearest, &found), GE_Result_NotInitialized);

    EXPECT_EQ(nearest, ECS::kInvalidEntity);
    EXPECT_EQ(found, 0u);
}

TEST_F(ScriptBindings, EntityCrossesAsItsPackedId)
{
    const GE_Probe_Table_v1& table = Table();
    const ECS::EntityHandle entity(5, 3);
    const Mathematics::Vector3 force{0.0f, 2.0f, 0.0f};

    ASSERT_EQ(table.Push(entity.id, &force), GE_Result_Ok);
    EXPECT_EQ(m_Probe.LastEntity, entity);
    EXPECT_EQ(m_Probe.LastForce.y, 2.0f);

    ASSERT_EQ(table.SetSpeed(entity.id, 4.5f), GE_Result_Ok);
    float speed = 0.0f;
    ASSERT_EQ(table.GetSpeed(entity.id, &speed), GE_Result_Ok);
    EXPECT_EQ(speed, 4.5f);

    m_Probe.Nearest = ECS::EntityHandle(9, 1);
    const Mathematics::Vector3 point{};
    std::uint32_t nearest = 0;
    std::uint8_t found = 0;
    ASSERT_EQ(table.TryNearest(&point, &nearest, &found), GE_Result_Ok);
    EXPECT_EQ(found, 1u);
    EXPECT_EQ(nearest, m_Probe.Nearest.id);
}

// Text crosses as UTF-8 with a length both ways: ASCII, a multi-byte name and the empty text arrive
// whole; a short buffer gets what fits and the full length, so the caller asks again; and a call that
// does not run answers the empty text.
TEST_F(ScriptBindings, TextRoundTripsAsUtf8WithItsLength)
{
    const GE_Probe_Table_v1& table = Table();
    const std::string_view grun = "Gr\xC3\xBCn \xE6\xA3\xAE"; // 9 bytes: a two-byte and a three-byte character
    for (const std::string_view text : {std::string_view("Props"), grun, std::string_view()})
    {
        char buffer[32] = {};
        std::int32_t length = -1;
        ASSERT_EQ(table.Echo(text.data(), static_cast<std::int32_t>(text.size()), buffer, sizeof(buffer), &length), GE_Result_Ok);
        EXPECT_EQ(m_Probe.LastText, text);
        ASSERT_EQ(length, static_cast<std::int32_t>(text.size()));
        EXPECT_EQ(std::string_view(buffer, static_cast<std::size_t>(length)), text);
    }

    char small[4] = {'x', 'x', 'x', 'x'};
    std::int32_t length = 0;
    ASSERT_EQ(table.Echo(grun.data(), static_cast<std::int32_t>(grun.size()), small, 3, &length), GE_Result_Ok);
    EXPECT_EQ(length, 9) << "the full length, never a silent truncation";
    EXPECT_EQ(std::string_view(small, 3), grun.substr(0, 3));
    EXPECT_EQ(small[3], 'x') << "nothing past the capacity is written";
    ASSERT_EQ(table.Echo(grun.data(), static_cast<std::int32_t>(grun.size()), nullptr, 0, &length), GE_Result_Ok);
    EXPECT_EQ(length, 9) << "a buffer of 0 asks the length";

    ProbeSystem::Current() = nullptr;
    length = 5;
    EXPECT_EQ(table.Echo("Props", 5, small, 4, &length), GE_Result_NotInitialized);
    EXPECT_EQ(length, 0);
}

TEST_F(ScriptBindings, TextWithoutItsBytesIsRefusedBeforeTheCall)
{
    const GE_Probe_Table_v1& table = Table();
    const std::uint32_t calls = ProbeSystem::Calls().load();
    char buffer[8] = {};
    std::int32_t length = 0;

    EXPECT_EQ(table.Echo(nullptr, 4, buffer, 8, &length), GE_Result_InvalidArg);
    EXPECT_NE(LastError().find("Probe.Echo: `text` is a null pointer"), std::string::npos) << LastError();
    EXPECT_EQ(table.Echo("abc", -1, buffer, 8, &length), GE_Result_InvalidArg);
    EXPECT_NE(LastError().find("Probe.Echo: `textLength` is negative"), std::string::npos) << LastError();
    EXPECT_EQ(table.Echo("abc", 3, nullptr, 8, &length), GE_Result_InvalidArg);
    EXPECT_EQ(table.Echo("abc", 3, buffer, -1, &length), GE_Result_InvalidArg);
    EXPECT_EQ(table.Echo("abc", 3, buffer, 8, nullptr), GE_Result_InvalidArg);

    EXPECT_EQ(ProbeSystem::Calls().load(), calls);
}

// A span of results gets the results that fit and always the full count: a buffer larger than, equal to
// and shorter than the results, and a buffer of 0, which asks the count. Nothing past the capacity is
// written, and a call that does not run answers 0.
TEST_F(ScriptBindings, SpanOfResultsGetsWhatFitsAndTheFullCount)
{
    const GE_Probe_Table_v1& table = Table();
    m_Probe.Hits = {Hit{{}, 1.0f, {}}, Hit{{}, 2.0f, {}}, Hit{{}, 3.0f, {}}};
    const Mathematics::Vector3 origin{0.0f, 0.0f, 0.0f};
    for (const std::int32_t capacity : {5, 3, 2})
    {
        Hit buffer[5];
        for (Hit& hit : buffer)
            hit.distance = -1.0f;
        std::int32_t count = -1;
        ASSERT_EQ(table.ListHits(&origin, buffer, capacity, &count), GE_Result_Ok) << capacity;
        EXPECT_EQ(count, 3) << "the full count, never a silent truncation; capacity " << capacity;
        for (std::int32_t i = 0; i < 5; ++i)
            EXPECT_EQ(buffer[i].distance, i < std::min(capacity, 3) ? static_cast<float>(i + 1) : -1.0f)
                << "capacity " << capacity << ", element " << i;
    }

    std::int32_t count = -1;
    ASSERT_EQ(table.ListHits(&origin, nullptr, 0, &count), GE_Result_Ok);
    EXPECT_EQ(count, 3) << "a buffer of 0 asks the count";

    ProbeSystem::Current() = nullptr;
    Hit buffer[1];
    EXPECT_EQ(table.ListHits(&origin, buffer, 1, &count), GE_Result_NotInitialized);
    EXPECT_EQ(count, 0);
}

TEST_F(ScriptBindings, SpanOfResultsWithoutItsBufferIsRefusedBeforeTheCall)
{
    const GE_Probe_Table_v1& table = Table();
    m_Probe.Hits = {Hit{}};
    const std::uint32_t calls = ProbeSystem::Calls().load();
    const Mathematics::Vector3 origin{0.0f, 0.0f, 0.0f};
    Hit buffer[2];
    std::int32_t count = 0;

    EXPECT_EQ(table.ListHits(&origin, nullptr, 2, &count), GE_Result_InvalidArg);
    EXPECT_NE(LastError().find("Probe.ListHits: `hits` is a null pointer"), std::string::npos) << LastError();
    EXPECT_EQ(table.ListHits(&origin, buffer, -1, &count), GE_Result_InvalidArg);
    EXPECT_NE(LastError().find("Probe.ListHits: `hitsCapacity` is negative"), std::string::npos) << LastError();
    EXPECT_EQ(table.ListHits(&origin, buffer, 2, nullptr), GE_Result_InvalidArg);
    EXPECT_NE(LastError().find("Probe.ListHits: `outResult` is a null pointer"), std::string::npos) << LastError();

    EXPECT_EQ(ProbeSystem::Calls().load(), calls);
}

// A mask crosses as its bits; a call that does not run answers no layer, never layer 0.
TEST_F(ScriptBindings, RenderLayerMaskCrossesAsItsBits)
{
    m_Probe.Layers = Rendering::RenderLayerMask::FromLayer(4);
    std::uint32_t previous = 7u;

    ASSERT_EQ(Table().SwapLayers(0b1010u, &previous), GE_Result_Ok);
    EXPECT_EQ(previous, 1u << 4);
    EXPECT_EQ(m_Probe.Layers.Bits, 0b1010u);

    ProbeSystem::Current() = nullptr;
    previous = 7u;
    EXPECT_EQ(Table().SwapLayers(1u, &previous), GE_Result_NotInitialized);
    EXPECT_EQ(previous, 0u);
}

// The layouts of the hand-written kinds of Scripting.Bindings that component mirrors hold
// (ColorLinear.cs, Curve.cs, CurveKey.cs, CurveInterp.cs, CurveTangentMode.cs, BoundingBox.cs).
// ComponentKindTests (Managed/BindingTests) reads the C# side at the same offsets.
static_assert(sizeof(GameEngine::ColorLinear) == 16 && offsetof(GameEngine::ColorLinear, r) == 0 &&
              offsetof(GameEngine::ColorLinear, g) == 4 && offsetof(GameEngine::ColorLinear, b) == 8 &&
              offsetof(GameEngine::ColorLinear, a) == 12);
static_assert(sizeof(GameEngine::Math::CurveKey) == 20 && offsetof(GameEngine::Math::CurveKey, Time) == 0 &&
              offsetof(GameEngine::Math::CurveKey, Value) == 4 && offsetof(GameEngine::Math::CurveKey, InTangent) == 8 &&
              offsetof(GameEngine::Math::CurveKey, OutTangent) == 12 && offsetof(GameEngine::Math::CurveKey, Interp) == 16 &&
              offsetof(GameEngine::Math::CurveKey, TangentMode) == 17);
static_assert(sizeof(GameEngine::Math::Curve) == 644 && offsetof(GameEngine::Math::Curve, KeyCount) == 0 &&
              offsetof(GameEngine::Math::Curve, Keys) == 4 && sizeof(GameEngine::Math::Curve::Keys) == 640);
static_assert(static_cast<int>(GameEngine::Math::CurveInterp::Linear) == 0 && static_cast<int>(GameEngine::Math::CurveInterp::Smooth) == 1 &&
              static_cast<int>(GameEngine::Math::CurveInterp::Step) == 2);
static_assert(static_cast<int>(GameEngine::Math::CurveTangentMode::Auto) == 0 &&
              static_cast<int>(GameEngine::Math::CurveTangentMode::Flat) == 1 &&
              static_cast<int>(GameEngine::Math::CurveTangentMode::Broken) == 2 &&
              static_cast<int>(GameEngine::Math::CurveTangentMode::Manual) == 3 &&
              static_cast<int>(GameEngine::Math::CurveTangentMode::Mirrored) == 4);
static_assert(sizeof(GameEngine::Mathematics::BoundingBox) == 24 && offsetof(GameEngine::Mathematics::BoundingBox, center) == 0 &&
              offsetof(GameEngine::Mathematics::BoundingBox, halfExtents) == 12);

// A linear color crosses by pointer as its four floats; a call that does not run answers the
// default color, opaque black.
TEST_F(ScriptBindings, ColorLinearCrossesAsFourFloats)
{
    m_Probe.Tint = ColorLinear(0.25f, 0.5f, 0.75f, 1.0f);
    const ColorLinear tint(1.0f, 0.0f, 0.5f, 0.25f);
    ColorLinear previous(9.0f, 9.0f, 9.0f, 9.0f);

    ASSERT_EQ(Table().SwapTint(&tint, &previous), GE_Result_Ok);
    EXPECT_EQ(previous, ColorLinear(0.25f, 0.5f, 0.75f, 1.0f));
    EXPECT_EQ(m_Probe.Tint, tint);

    ProbeSystem::Current() = nullptr;
    previous = ColorLinear(9.0f, 9.0f, 9.0f, 9.0f);
    EXPECT_EQ(Table().SwapTint(&tint, &previous), GE_Result_NotInitialized);
    EXPECT_EQ(previous, ColorLinear{});
}

namespace
{
struct TouchLog
{
    int Calls = 0;
    int Ended = 0;
    Touch Last{};
};

void OnTouch(const Touch* payload, void* user)
{
    TouchLog& log = *static_cast<TouchLog*>(user);
    ++log.Calls;
    log.Last = *payload;
}

void OnTouchEnded(void* user)
{
    ++static_cast<TouchLog*>(user)->Ended;
}
} // namespace

// The subscribe entry hands the facade the callback as it crossed, the unsubscribe entry ends it, and
// the callback's Ended runs once; an invalid scope and a callback with no Invoke are refused first.
TEST_F(ScriptBindings, EventSubscribesAndEndsThroughItsTwoEntries)
{
    const GE_Probe_Table_v1& table = Table();
    TouchLog log;
    const ScriptCallback<Touch> callback{&OnTouch, &OnTouchEnded, &log};
    const ECS::EntityHandle scope(7, 2);
    std::uint64_t subscription = 0;

    ASSERT_EQ(table.SubscribeTouched(scope.id, &callback, &subscription), GE_Result_Ok);
    ASSERT_NE(subscription, 0u);
    const ProbeSystem::TouchSubscription& touched = ProbeSystem::Touched();
    EXPECT_EQ(touched.Scope, scope);
    Touch touch;
    touch.self = scope;
    touch.force = 3.0f;
    touched.Callback.Invoke(&touch, touched.Callback.User);
    EXPECT_EQ(log.Calls, 1);
    EXPECT_EQ(log.Last.force, 3.0f);

    ASSERT_EQ(table.UnsubscribeTouched(subscription), GE_Result_Ok);
    ASSERT_EQ(table.UnsubscribeTouched(subscription), GE_Result_Ok);
    EXPECT_EQ(log.Ended, 1);

    const std::uint32_t calls = ProbeSystem::Calls().load();
    std::uint64_t refused = 5;
    EXPECT_EQ(table.SubscribeTouched(ECS::EntityHandle().id, &callback, &refused), GE_Result_InvalidArg);
    EXPECT_EQ(refused, 0u);
    EXPECT_NE(LastError().find("Probe.SubscribeTouched: `scope` is Entity.None"), std::string::npos) << LastError();
    const ScriptCallback<Touch> noInvoke{nullptr, &OnTouchEnded, &log};
    EXPECT_EQ(table.SubscribeTouched(scope.id, &noInvoke, &refused), GE_Result_InvalidArg);
    EXPECT_EQ(ProbeSystem::Calls().load(), calls);
}

TEST_F(ScriptBindings, ExceptionIsCaughtAsFail)
{
    EXPECT_EQ(Table().Throw(), GE_Result_Fail);

    EXPECT_NE(LastError().find("Probe.Throw failed: the probe throws"), std::string::npos) << LastError();
}
